    for i in range(n):
        # Count pair (i, i) if |a[i] - a[i]| == k (which means k == 0)
        if abs(a[i] - a[i]) == k:
            count += 1
        for j in range(i + 1, n):
            if abs(a[i] - a[j]) == k:
