                if i == len(s):
                    return -1
                if s[i] == ' ':
                    return i
                return find_space_index(s, i+1)
            idx = find_space_index(string)
            if idx == -1:
                return acc + [string]
            else:
                return split_by_space(string[idx+1:], acc + [string[:idx]])

