        if not n.isdigit():
            return "not prime"  # Non-digit strings are not prime numbers
        n = int(n)
    elif not isinstance(n, int):
        return "not prime"

    if n <= 1:
        return "not prime"
    if n <= 3:
        return "prime"
    if n % 2 == 0 or n % 3 == 0:
        return "not prime"
    i = 5
