    if x < 0:
        raise ValueError("Input must be a non-negative integer")

    # Find the position of the leftmost set bit
    bit_length = x.bit_length()

    # If all bits up to bit_length are set, the leftmost unset bit is just beyond them
    # For example, if x = 0b111 (7), bit_length=3, leftmost unset bit is at position 3 (0-indexed)
    # So set bit at position bit_length
    # Otherwise, find the leftmost unset bit inside bit_length bits

    # Iterate from the most significant bit down to 0
    for pos in reversed(range(bit_length)):
        if not (x & (1 << pos)):
            return x | (1 << pos)

    # If no unset bit found in existing bits, set the next bit
    return x | (1 << bit_length)

