    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    histogram(123) == {1: 1, 2: 1, 3: 1}

    """
    # Convert input to list of elements without using string methods or loops
    def to_list(x):
        # If input is int, convert to string by str and then to list of int digits
        if isinstance(x, int):
            s = str(x)
            # helper to convert string s to list of ints recursively
            def to_int_list(i):
                if i == len(s):
                    return []
                return [ord(s[i]) - ord('0')] + to_int_list(i+1)
            return to_int_list(0)
        # If input is string, split by spaces recursively without using str methods
        if isinstance(x, str):
            def split_spaces(i, start):
                if i == len(x):
                    # last word
                    return [slice_to_val(x, start, i)] if start < i else []
                if x[i] == ' ':
                    # found space, slice word and continue
                    return [slice_to_val(x, start, i)] + split_spaces(i+1, i+1)
                else:
                    return split_spaces(i+1, start)
            # Convert slice of string to value (string)
            def slice_to_val(s, start, end):
                # build string recursively without string methods
                def build_str(i):
                    if i == end:
                        return ''
                    # concatenate character by character
                    return s[i] + build_str(i+1)
                return build_str(start)
            return split_spaces(0,0)
        # If input is already list or other iterable, convert to list recursively
        try:
            # Try to get first element and rest recursively
            def to_list_iter(seq, i=0):
                try:
                    seq[i]
                except:
                    return []
                return [seq[i]] + to_list_iter(seq, i+1)
            return to_list_iter(x)
        except:
            # If none fits, return empty list
            return []

    elems = to_list(test)

    # Count occurrences recursively without loops
    def count_all(lst, counted=None):
        if counted is None:
            counted = {}
        if not lst:
            return counted
        head = lst[0]
        # count head in counted
        def inc_count(d, key):
            if key in d:
                d[key] = d[key] + 1
            else:
                d[key] = 1
            return d
        inc_count(counted, head)
        return count_all(lst[1:], counted)

    counts = count_all(elems)

    if not counts:
