    # find max count value without loop
    def max_count(d):
        keys = list(d.keys())
        def max_helper(i, current_max):
            if i == len(keys):
                return current_max
            v = d[keys[i]]
            return max_helper(i+1, v if v > current_max else current_max)
        return max_helper(0, d[keys[0]])

    maximum = max_count(counts)

    # filter dictionary to keep only max counts, preserving original order in elems
    def filter_max(lst, counts, maxv, acc=None):
        if acc is None:
            acc = {}
        if not lst:
